     SolrIndexSplitter splitter = new SolrIndexSplitter(cmd);
     splitCommands.mark();
     try {
       splitter.split();
     } catch (IOException e) {
       numErrors.increment();
       numErrorsCumulative.mark();
+      throw e;
     }
   }



